'use strict';

const mongoose = require('mongoose');
const { ASSET_STATUSES, ASSET_CATEGORIES } = require('../config/constants');

const assetSchema = new mongoose.Schema(
  {
    tenantId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Tenant',
      required: true,
    },
    qrToken: {
      type: String,
      required: true,
      // 64-char lowercase hex; generated by QRService, never supplied by caller
    },
    assetCode: {
      type: String,
      required: true,
      trim: true,
      uppercase: true,
    },
    name: {
      type: String,
      required: true,
      trim: true,
      maxlength: 200,
    },
    category: {
      type: String,
      required: true,
      enum: ASSET_CATEGORIES,
    },
    description: {
      type: String,
      trim: true,
      maxlength: 1000,
      default: null,
    },
    serialNumber: {
      type: String,
      trim: true,
      maxlength: 100,
      default: null,
    },
    status: {
      type: String,
      required: true,
      enum: ASSET_STATUSES,
      default: 'Available',
    },
    assignedEmployeeId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Employee',
      default: null,
    },
    assignedLocationId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Location',
      default: null,
    },
    isPublicVisible: {
      type: Boolean,
      required: true,
      default: true,
    },
  },
  {
    timestamps: true,
    collection: 'assets',
  }
);

// Indexes — as specified in ARCHITECTURE.md §2.6
assetSchema.index({ qrToken: 1 }, { unique: true });
assetSchema.index({ tenantId: 1, assetCode: 1 }, { unique: true });
assetSchema.index({ tenantId: 1, status: 1 });
assetSchema.index({ tenantId: 1, category: 1 });
assetSchema.index({ tenantId: 1, assignedEmployeeId: 1 });
assetSchema.index({ tenantId: 1, assignedLocationId: 1 });

// toJSON: strip internal/sensitive fields, expose id as string
// qrToken IS included here — authenticated callers receive it; public endpoint
// uses a separate projection that manually omits it.
assetSchema.set('toJSON', {
  virtuals: false,
  transform(_doc, ret) {
    ret.id = ret._id.toString();
    delete ret._id;
    delete ret.__v;
    delete ret.tenantId; // never returned per field-level rules
    // Stringify ObjectId references so they serialise as strings
    if (ret.assignedEmployeeId) {
      ret.assignedEmployeeId = ret.assignedEmployeeId.toString();
    }
    if (ret.assignedLocationId) {
      ret.assignedLocationId = ret.assignedLocationId.toString();
    }
    return ret;
  },
});

module.exports = mongoose.model('Asset', assetSchema);
